    21→        IF: {
    22→          instruction: null,
    23→          pc: 0,
    24→          active: false
    25→        },
    26→        ID: {
    27→          instruction: null,
    28→          opcode: '',
    29→          rs: 0,
    30→          rt: 0,
    31→          rd: 0,
    32→          imm: 0,
    33→          rsVal: 0,
    34→          rtVal: 0,
    35→          active: false
    36→        },
