test('BEQ branches when equal', function() {
  const program = [
    InstructionSet.createInstruction('ADDI', { rs: 0, rt: 8, immediate: 10 }),
    InstructionSet.createInstruction('BEQ', { rs: 8, rt: 8, immediate: 2 }),
    InstructionSet.createInstruction('ADDI', { rs: 0, rt: 9, immediate: 99 })  // Should be skipped
  ];
  const result = SequenceGenerator.generateSequence(program);
  const lastFrame = result.frames[result.frames.length - 1];
  // PC should skip over the third instruction
  // After BEQ at PC=4, branch taken means PC = 4 + 2*4 = 12
  assertEquals(lastFrame.pc, 12, 'PC should be 12 after branch');
  assertEquals(lastFrame.getRegister(9), 0, 'Register $9 should still be 0 (instruction skipped)');
});

